fn process_order_by(
        &mut self,
        mut lf: LazyFrame,
        order_by: &Option<OrderBy>,
        selected: Option<&[Expr]>,
    ) -> PolarsResult<LazyFrame> {
        if order_by.as_ref().is_none_or(|ob| match &ob.kind {
            OrderByKind::Expressions(exprs) => exprs.is_empty(),
            OrderByKind::All(_) => false,
        }) {
            return Ok(lf);
        }
        let schema = self.get_frame_schema(&mut lf)?;
        let columns_iter = schema.iter_names().map(|e| col(e.clone()));
        let (order_by, order_by_all, n_order_cols) = match &order_by.as_ref().unwrap().kind {
            OrderByKind::Expressions(exprs) => {


                if exprs.len() == 1
                    && matches!(&exprs[0].expr, SQLExpr::Identifier(ident)
                        if ident.value.to_uppercase() == "ALL"
                        && !schema.iter_names().any(|name| name.to_uppercase() == "ALL"))
                {

                    let n_cols = if let Some(selected) = selected {
                        selected.len()
                    } else {
                        schema.len()
                    };
                    (vec![], Some(&exprs[0].options), n_cols)
                } else {
                    (exprs.clone(), None, exprs.len())
                }
            },
            OrderByKind::All(opts) => {
                let n_cols = if let Some(selected) = selected {
                    selected.len()
                } else {
                    schema.len()
                };
                (vec![], Some(opts), n_cols)
            },
        };
        let mut descending = Vec::with_capacity(n_order_cols);
        let mut nulls_last = Vec::with_capacity(n_order_cols);
        let mut by: Vec<Expr> = Vec::with_capacity(n_order_cols);

        if let Some(opts) = order_by_all {
            if let Some(selected) = selected {
                by.extend(selected.iter().cloned());
            } else {
                by.extend(columns_iter);
            };
            let options = order_by_sort_options(opts);
            nulls_last.resize(by.len(), options.nulls_last);
            descending.resize(by.len(), options.descending);
        } else {
            let columns = &columns_iter.collect::<Vec<_>>();


            let mut bindings = SubqueryBindings::new();
            for ob in order_by {
                let options = order_by_sort_options(&ob.options);
                nulls_last.push(options.nulls_last);
                descending.push(options.descending);

                let lowered;
                (lf, lowered) = self.lower_correlated_subqueries(
                    lf,
                    &schema,
                    &ob.expr,
                    LowerScope::ScalarAndPredicates,
                    &mut bindings,
                    None,
                )?;


                let lowered_schema = match &lowered {
                    Cow::Owned(_) => self.get_frame_schema(&mut lf)?,
                    Cow::Borrowed(_) => schema.clone(),
                };

                by.push(self.marking_aggregates(|ctx| {
                    ctx.expr_or_ordinal(
                        &lowered,
                        columns,
                        selected,
                        Some(&lowered_schema),
                        "ORDER BY",
                    )
                })?)
            }
        }

        let mut by: Vec<Expr> = by.into_iter().map(strip_aggregate_marks).collect();
        let subquery_names;
        (lf, subquery_names) =
            self.process_subqueries(lf, by.iter_mut().collect(), SubqueryShape::Broadcast)?;

        let sorted = lf.sort_by_exprs(
            &by,
            SortMultipleOptions::default()
                .with_order_descending_multi(descending)
                .with_nulls_last_multi(nulls_last),
        );
        Ok(drop_subquery_placeholders(sorted, subquery_names))
    }

